def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]

    # Full horizontal bars are the row-wise version of the same repeating pattern.
    bars = {}
    for r in range(h):
        vals = [v for v in grid[r] if v]
        if len(vals) >= w // 2:
            bars[r] = vals[0]

    def find_period(items, limit):
        """Smallest period for which equal residues have equal colors."""
        for p in range(1, limit + 1):
            residues = {}
            valid = True
            for pos, color in items:
                residue = pos % p
                if residue in residues and residues[residue] != color:
                    valid = False
                    break
                residues[residue] = color
            if valid:
                return p, residues
        return limit, {}

    if bars:
        p, pattern = find_period(list(bars.items()), max(h, 1))
        fallback = bars[max(bars, key=lambda r: sum(v != 0 for v in grid[r]))]
        return [[pattern.get(r % p, fallback) for _ in range(w)] for r in range(h)]

    # Determine which diagonal direction the clues follow.
    def concentration(fn):
        counts = {}
        for r, c, _ in points:
            d = fn(r, c)
            counts[d] = counts.get(d, 0) + 1
        return sum(n * n for n in counts.values())

    diff = lambda r, c: c - r
    summ = lambda r, c: c + r
    offset = diff if concentration(diff) >= concentration(summ) else summ

    # Collapse the clues to diagonal intercepts, then infer the smallest
    # repeating period consistent with all of them.
    lines = {}
    for r, c, color in points:
        lines[offset(r, c)] = color
    p, pattern = find_period(list(lines.items()), max(h, w))

    # Any unmarked residue inherits the most common clue color.
    counts = {}
    for _, _, color in points:
        counts[color] = counts.get(color, 0) + 1
    fallback = max(counts, key=counts.get)
    return [[pattern.get(offset(r, c) % p, fallback) for c in range(w)]
            for r in range(h)]
